    if nchar == 7 and substr:
        return "%Y-%m"
    if nchar == 10 and substr:
        return "%Y-%m-%d"
    if nchar == 13 and substr:
        return "%Y-%m-%d %H"
    if nchar == 16 and substr:
        return "%Y-%m-%d %H:%M"
    if nchar == 19 and substr:
        return "%Y-%m-%d %H:%M:%S"
    if nchar >= 20 and substr and c1[19] == ".":
