    if nchar == 8 and not substr:
        return "%Y%m%d"
    if nchar == 10 and not substr:
        return "%Y%m%d%H"
    if nchar == 12 and not substr:
        return "%Y%m%d%H%M"
    if nchar == 14 and not substr:
        return "%Y%m%d%H%M%S"
    return "unknown"

def time_date(charvec, format_val=None, zone="GMT", fin_center="GMT"):
    tz = pytz.timezone(zone)
